def subtract(a, b):
    # Filter out empty intervals and sort
    a_intervals = sorted([interval for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([interval for interval in b if interval[0] < interval[1]])

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and start <= merged_b[-1][1]:
            # Overlapping or touching - merge
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # For each interval in a, subtract all intervals in merged_b
    result = []

    for a_start, a_end in a_intervals:
        current_intervals = [[a_start, a_end]]

        # Subtract each b interval from current_intervals
        for b_start, b_end in merged_b:
            next_intervals = []
            for curr_start, curr_end in current_intervals:
                # No overlap
                if curr_end <= b_start or curr_start >= b_end:
                    next_intervals.append([curr_start, curr_end])
                else:
                    # There is overlap - keep the parts that don't overlap
                    if curr_start < b_start:
                        next_intervals.append([curr_start, b_start])
                    if curr_end > b_end:
                        next_intervals.append([b_end, curr_end])
            current_intervals = next_intervals

        result.extend(current_intervals)

    # Sort result
    result.sort()

    # Merge touching intervals
    merged_result = []
    for start, end in result:
        if merged_result and start == merged_result[-1][1]:
            # Touching - merge
            merged_result[-1][1] = end
        else:
            merged_result.append([start, end])

    return merged_result

